"""CLF-C02 Domain 3 (Cloud Technology and Services) and Domain 4 (Billing, Pricing, and Support)."""
from _awshelp import A, D, E, L, cfg, clab, qa
from builder import animation

T = "frontend/src/simulations/groups/aws.test.ts"
ids = lambda p, n: [f"CLFC02-{p}.{i}" for i in range(1, n + 1)]  # noqa: E731
animation("aws-tech-sim", "VPC reachability, global infrastructure and service selection", E,
          ids("3.1", 6) + ids("3.2", 8) + ids("3.3", 6) + ids("3.4", 7) + ids("3.5", 5) + ids("3.6", 8) + ids("3.7", 4) + ids("3.8", 14), "accurate-model", T,
          "Configure a VPC until a web server is reachable, survive AZ/Region failures, and choose compute, database, network, storage, AI/analytics and other services.")
animation("aws-billing-sim", "Purchasing options, data transfer, consolidated billing and support", E, ids("4.1", 7) + ids("4.2", 8) + ids("4.3", 13), "simplified-illustration", T,
          "Compare purchasing options, learn which data transfer is charged, see RI sharing in Organizations, and pick billing tools and support resources.")


def pairs(obj_prefix, items, doc_default):
    """items: (n, recall stem, recall options, applied stem, applied options[, doc])"""
    for it in items:
        n, s1, o1, s2, o2 = it[:5]
        doc = it[5] if len(it) > 5 else doc_default
        qa(f"CLFC02-{obj_prefix}.{n}", 1, "single", s1, o1, "a", o1[0][1] if not o1[0][1].startswith("Correct") else "The first option is the documented behaviour; see the lesson.", doc)
        qa(f"CLFC02-{obj_prefix}.{n}", 2, "scenario", s2, o2, "a", o2[0][1] if not o2[0][1].startswith("Correct") else "Applied: the first option best meets the requirement.", doc)


