pairs("3.1", [
    (1, "Which tool provisions AWS resources from a template?", [("AWS CloudFormation", "Correct."), ("Amazon Polly", "No."), ("AWS Artifact", "No."), ("Amazon SES", "No.")], "You must create the same VPC layout in many accounts. What should you use?", [("AWS CloudFormation (StackSets for many accounts)", "Correct."), ("Manual console steps", "Error-prone."), ("AWS Support", "No."), ("Amazon Lex", "No.")], D + "AWSCloudFormation/latest/UserGuide/Welcome.html"),
    (2, "Which is a way to access AWS services programmatically from application code?", [("AWS SDKs", "Correct."), ("AWS Artifact", "No."), ("AWS Marketplace", "No."), ("Edge locations", "No.")], "An admin needs to run AWS commands from a browser on a locked-down laptop. What should they use?", [("AWS CloudShell", "Correct."), ("Install SDKs locally", "Not possible here."), ("AWS Outposts", "No."), ("Snowball", "No.")], D + "cloudshell/latest/userguide/welcome.html"),
    (3, "Which deployment model runs some workloads on premises and some in AWS, connected together?", [("Hybrid", "Correct."), ("All-in cloud", "No."), ("On-premises only", "No."), ("Edge only", "No.")], "A factory needs AWS services with single-digit millisecond latency on its own site. Which offering supports this hybrid model?", [("AWS Outposts", "Correct."), ("Amazon Lightsail", "No."), ("AWS Artifact", "No."), ("Amazon Polly", "No.")], D + "outposts/latest/userguide/what-is-outposts.html"),
    (4, "When is the AWS Management Console the best choice?", [("Exploring services or performing a one-time task", "Correct."), ("Deploying 500 identical stacks", "Use IaC."), ("Nightly automation", "Use scripts."), ("CI/CD", "Use pipelines.")], "A developer's application must upload files to S3. Which access method fits?", [("An AWS SDK called from the application", "Correct."), ("The console", "Manual."), ("CloudFormation", "Provisioning, not runtime uploads."), ("Trusted Advisor", "No.")], D + "cli/latest/userguide/cli-chap-welcome.html"),
    (5, "Which approach suits a process you will repeat many times?", [("Automate it with scripts or IaC", "Correct."), ("Do it manually each time", "Error-prone."), ("Use the root user", "No."), ("Open a support case", "No.")], "A one-time change to an S3 bucket's tags is needed. What is reasonable?", [("Make the change in the console", "Correct: one-time operation."), ("Write a CloudFormation template", "Overkill for once."), ("Build a CI pipeline", "Overkill."), ("Buy Savings Plans", "Unrelated.")], A + "console/"),
    (6, "Which is a cloud deployment model?", [("All-in cloud, where all parts of the application run in the cloud", "Correct."), ("Region-only", "Not a model."), ("Edge-only", "No."), ("Spot-only", "Pricing.")], "A bank keeps its core ledger in its own data center and runs new apps in AWS, connected by Direct Connect. Which model?", [("Hybrid", "Correct."), ("Cloud", "Not entirely."), ("On-premises", "Not entirely."), ("Multi-Region", "Different concept.")], A + "what-is-cloud-computing/"),
], A + "console/")

