L(id="clf-global-infrastructure", title="AWS global infrastructure: Regions, Availability Zones and edge locations", objectives=ids("3.2", 8), minutes=35,
  objective="Describe Regions, Availability Zones and edge locations, how they relate, how to achieve high availability with multiple AZs, and when to use multiple Regions.",
  prereqs=[("Benefits of the AWS Cloud", "CLFC02-1.1.2", "clf-benefits")],
  foundation=["A Region is a geographic area (for example eu-west-1, Ireland) with several Availability Zones.", "An Availability Zone (AZ) is one or more discrete data centers with redundant power, networking and connectivity, isolated from other AZs but connected by fast, low-latency links.",
              "Edge locations are sites near users that CloudFront, Route 53 and Global Accelerator use to deliver content and DNS quickly."],
  engineer=["Regions are fully isolated from each other; most services are Regional, some are global (IAM, Route 53, CloudFront). Choose a Region by compliance/data sovereignty, proximity to users, service availability and price.",
            "AZs: each Region has at least three AZs; AZs are physically separated so they do not share single points of failure. Deploy across at least two AZs with Elastic Load Balancing and Auto Scaling; managed services offer Multi-AZ options (RDS Multi-AZ, S3 stores data across AZs by default for most classes).",
            "Multiple Regions: disaster recovery and business continuity, low latency for global users, data sovereignty requirements, and resilience to Regional events.",
            "Edge: CloudFront caches content; Route 53 answers DNS at the edge; Global Accelerator routes users over the AWS network. Local Zones place compute closer to population centers; Wavelength Zones sit in telecom 5G networks."],
  anim=("aws-tech-sim", "Open 'AZs, Regions and edge locations' and inject failures."),
  diagram=([("r1", "Region eu-west-1", 150, 0, "globe"), ("a", "AZ a", 0, 120, "compute"), ("b", "AZ b", 150, 120, "compute"), ("c", "AZ c", 300, 120, "compute"), ("r2", "Region us-east-1 (DR)", 520, 0, "globe"), ("edge", "Edge locations", 520, 160, "network")],
           [("r1", "a"), ("r1", "b"), ("r1", "c"), ("r1", "r2", "replication"), ("edge", "r1", "CloudFront origin")]),
  example=("Resilient e-commerce", ["The shop runs in three AZs in Frankfurt behind an Application Load Balancer, with RDS Multi-AZ. A pilot-light copy in another Region covers Regional disasters, and CloudFront serves images worldwide."]),
  config=cfg(["EC2 > Launch instance > Subnet: choose AZs.", "RDS > Multi-AZ deployment.", "CloudFront > Create distribution."], "aws ec2 describe-availability-zones --output table\naws ec2 describe-regions --all-regions --output table", "Get-EC2AvailabilityZone\nGet-EC2Region"),
  lab=dict(type="A", objective="See which deployment survives which failure.", duration=10, steps=["Run the default (multi-AZ, AZ failure).", "Apply 'Region outage' and 'Single AZ'."], expected=["Multi-AZ survives AZ loss; multi-Region survives Region loss"], validation=[("aws-ha-ok", "Kept the app available"), ("aws-ha-outage", "Caused an outage")], failures=["Single AZ"]),
  troubleshooting=[("Outage when one AZ fails.", "All instances in one AZ.", "Spread across AZs with ELB and Auto Scaling."), ("Slow for users on another continent.", "Single distant Region.", "CloudFront, or deploy nearer.")],
  comparisons=[("Azure regions/zones", "Equivalent; Azure also defines region pairs.")],
  misconceptions=[("An AZ is a single data center.", "An AZ is one or more data centers."), ("Edge locations run EC2 instances.", "They host CloudFront/Route 53 and similar edge services.")],
  decisions=["Multi-AZ for high availability; multi-Region for DR, latency or sovereignty."],
  docs=[("Regions and Availability Zones", A + "about-aws/global-infrastructure/regions_az/"), ("AWS global infrastructure", A + "about-aws/global-infrastructure/"), ("Amazon CloudFront", D + "AmazonCloudFront/latest/DeveloperGuide/Introduction.html"), ("Fault isolation boundaries", D + "whitepapers/latest/aws-fault-isolation-boundaries/abstract-and-introduction.html")])
pairs("3.2", [
    (1, "What is an Availability Zone?", [("One or more discrete data centers with redundant power and networking in a Region", "Correct."), ("A CDN cache", "Edge location."), ("A country", "No."), ("A VPC", "No.")], "Which is the correct hierarchy?", [("A Region contains multiple AZs; edge locations are separate sites closer to users", "Correct."), ("An AZ contains Regions", "Reversed."), ("Edge locations contain AZs", "No."), ("A VPC contains Regions", "No.")]),
    (2, "How do you achieve high availability for an EC2 web tier?", [("Run instances in multiple AZs behind a load balancer", "Correct."), ("Use a bigger instance", "Single point of failure."), ("Use one AZ with backups", "Backups are not HA."), ("Use Dedicated Hosts", "No.")], "An app must keep serving if an AZ fails. What is the minimum design?", [("Instances in at least two AZs with Elastic Load Balancing and Auto Scaling", "Correct."), ("Two instances in the same AZ", "Same failure domain."), ("A larger EBS volume", "No."), ("CloudTrail", "No.")]),
    (3, "Why use multiple Regions?", [("Disaster recovery, lower latency for global users and data sovereignty", "Correct."), ("Required for every app", "No."), ("To avoid IAM", "No."), ("To get free data transfer", "Inter-Region is charged.")], "EU customer data must stay in the EU while US users need low latency. What do you do?", [("Deploy separate stacks in EU and US Regions, keeping EU data in the EU Region", "Correct."), ("One US Region for all", "Violates residency."), ("Edge locations only", "Do not store primary data."), ("One AZ in the EU", "Latency for US users.")]),
    (4, "What is a benefit of edge locations?", [("Lower latency by caching content closer to users", "Correct."), ("Running databases", "No."), ("Hosting IAM", "No."), ("Storing backups", "No.")], "Videos load slowly for users in South America. What helps most quickly?", [("Serve them through Amazon CloudFront", "Correct."), ("Bigger EC2 instances", "Latency is distance-bound."), ("RDS Multi-AZ", "No."), ("AWS Artifact", "No.")]),
    (5, "Which statement about Regions, AZs and edge locations is true?", [("Regions contain AZs; edge locations are more numerous and located near users", "Correct."), ("Each AZ is a separate Region", "No."), ("Edge locations are inside AZs only", "No."), ("There is one AZ per Region", "At least three.")], "Which services commonly use edge locations?", [("Amazon CloudFront and Amazon Route 53", "Correct."), ("Amazon RDS", "Regional."), ("Amazon EBS", "AZ-scoped."), ("AWS Batch", "Regional.")]),
    (6, "What is the effect of deploying across multiple AZs?", [("The application tolerates the failure of a single AZ", "Correct."), ("Lower cost always", "Not necessarily."), ("Automatic multi-Region DR", "No."), ("No need for backups", "Still needed.")], "An RDS database must fail over automatically within the Region if its AZ fails. What do you enable?", [("RDS Multi-AZ", "Correct."), ("Read replicas in another Region only", "Not automatic failover."), ("CloudFront", "No."), ("S3 lifecycle", "No.")], D + "AmazonRDS/latest/UserGuide/Concepts.MultiAZ.html"),
    (7, "Do Availability Zones in a Region share single points of failure?", [("No; they are isolated with separate power, networking and connectivity", "Correct."), ("Yes; they share one power grid", "No."), ("They share one data center", "No."), ("They share hardware", "No.")], "Why does AWS place AZs physically apart?", [("So a disaster at one AZ (fire, flood, power) does not affect others", "Correct."), ("To raise prices", "No."), ("To reduce latency to zero", "No."), ("For edge caching", "No.")]),
    (8, "When should you use multiple Regions?", [("For disaster recovery against a Regional outage", "Correct."), ("To survive a single instance failure", "Auto Scaling suffices."), ("To survive an AZ failure", "Multi-AZ suffices."), ("To use IAM", "IAM is global.")], "A business continuity plan requires surviving the loss of an entire Region. What must the architecture include?", [("A copy of the workload and data in a second Region", "Correct."), ("More AZs in the same Region", "Not enough."), ("Larger instances", "No."), ("Shield Advanced", "DDoS only.")]),
], A + "about-aws/global-infrastructure/regions_az/")

