# ---------------------------------------------------------------- 3.5
L(id="clf-networking", title="AWS network services: VPC, security, Route 53 and connectivity", objectives=ids("3.5", 5), minutes=40,
  objective="Identify VPC components, understand security groups and network ACLs (plus Inspector), describe Route 53, and choose connectivity options such as VPN and Direct Connect.",
  prereqs=[("Global infrastructure", "CLFC02-3.2.1", "clf-global-infrastructure")],
  foundation=["Amazon VPC is your own isolated network in AWS, divided into subnets in different AZs.", "Security groups act as firewalls for instances (stateful, allow rules only); network ACLs filter traffic at the subnet level (stateless, allow and deny rules).",
              "Route 53 is AWS's DNS service. Connect your office or data center with AWS VPN (encrypted over the internet) or AWS Direct Connect (private dedicated connection)."],
  engineer=["VPC components: CIDR block, subnets (public: route to an internet gateway; private: no direct internet route), route tables, internet gateway, NAT gateway (outbound internet for private subnets), VPC endpoints/PrivateLink, VPC peering, Transit Gateway, Elastic IPs.",
            "Security groups: attached to ENIs/instances, allow rules only, stateful (return traffic allowed). Network ACLs: per subnet, numbered allow/deny rules evaluated in order, stateless (allow ephemeral ports for responses). Amazon Inspector checks network reachability and vulnerabilities; AWS Network Firewall adds managed stateful inspection.",
            "Amazon Route 53: domain registration, DNS hosting, health checks, routing policies (simple, weighted, latency, failover, geolocation, geoproximity, multivalue).",
            "Connectivity: AWS Site-to-Site VPN, AWS Client VPN, AWS Direct Connect (dedicated or hosted connections; consistent latency; not encrypted by default), AWS Global Accelerator, CloudFront, API Gateway."],
  anim=("aws-tech-sim", "Open 'VPC: reach a web server' and fix the configuration."),
  diagram=([("inet", "Internet", 0, 60, "globe"), ("igw", "Internet gateway", 170, 60, "network"), ("rt", "Route table 0.0.0.0/0 → igw", 340, 60, "network"), ("nacl", "Network ACL (stateless)", 510, 60, "security"), ("sg", "Security group (stateful)", 680, 60, "security"), ("ec2", "EC2 (public IP)", 850, 60, "compute")],
           [("inet", "igw"), ("igw", "rt"), ("rt", "nacl"), ("nacl", "sg"), ("sg", "ec2")]),
  example=("A standard two-tier VPC", ["Web servers sit in public subnets in two AZs behind an ALB; databases sit in private subnets with no internet route, reaching updates through a NAT gateway. Security groups allow 443 to the ALB and only the ALB's security group to the web servers. Route 53 latency routing sends users to the nearest Region; the head office connects with Direct Connect plus a VPN backup."]),
  config=cfg(["VPC > Your VPCs > Create VPC (VPC and more).", "VPC > Security groups / Network ACLs.", "Route 53 > Hosted zones."], "aws ec2 describe-vpcs\naws ec2 describe-route-tables --filters Name=vpc-id,Values=<vpc-id>\naws ec2 describe-security-groups --group-ids <sg-id>\naws route53 list-hosted-zones", "Get-EC2Vpc\nGet-EC2RouteTable\nGet-EC2SecurityGroup\nGet-R53HostedZoneList"),
  lab=dict(type="A", objective="Make an EC2 web server reachable, step by step.", duration=15, steps=["Run the default and find the failing stage.", "Fix it, then apply each preset and fix again."], expected=["All five layers must allow traffic"], validation=[("aws-vpc-blocked", "Diagnosed a blocked path"), ("aws-vpc-ok", "Made the server reachable")], failures=["No route to IGW", "NACL without ephemeral ports", "SG without 443"]),
  troubleshooting=[("Instance unreachable although the SG allows 443.", "No IGW route or public IP, or NACL blocking.", "Check route table, public IP and NACL in/out rules."), ("Responses dropped.", "NACL outbound blocks ephemeral ports.", "Allow 1024–65535 outbound in the NACL.")],
  comparisons=[("Azure VNet/NSG", "NSGs are stateful with allow and deny rules and priorities; AWS splits into stateful allow-only SGs and stateless NACLs.")],
  misconceptions=[("Security groups can deny traffic.", "They contain allow rules only."), ("NACLs are stateful.", "NACLs are stateless.")],
  decisions=["Use private subnets for data tiers; restrict SGs by referencing other SGs."],
  docs=[("What is Amazon VPC?", D + "vpc/latest/userguide/what-is-amazon-vpc.html"), ("Security groups", D + "vpc/latest/userguide/vpc-security-groups.html"), ("Network ACLs", D + "vpc/latest/userguide/vpc-network-acls.html"),
        ("Amazon Route 53", D + "Route53/latest/DeveloperGuide/Welcome.html"), ("AWS Direct Connect", D + "directconnect/latest/UserGuide/Welcome.html"), ("AWS Site-to-Site VPN", D + "vpn/latest/s2svpn/VPC_VPN.html")])
pairs("3.5", [
    (1, "Which service lets you provision a logically isolated network in AWS?", [("Amazon VPC", "Correct."), ("Amazon Route 53", "DNS."), ("AWS Direct Connect", "Connectivity."), ("Amazon CloudFront", "CDN.")], "Which service gives private instances outbound internet access without inbound exposure?", [("NAT gateway", "Correct."), ("Internet gateway alone", "Needs public IPs."), ("Route 53", "DNS."), ("Security group", "Filtering.")], D + "vpc/latest/userguide/vpc-nat-gateway.html"),
    (2, "What makes a subnet public?", [("Its route table has a route to an internet gateway", "Correct."), ("Its name contains 'public'", "No."), ("It has a NACL", "All subnets do."), ("It is in us-east-1", "No.")], "A database must not be reachable from the internet. Where should it go?", [("A private subnet without a route to the internet gateway", "Correct."), ("A public subnet with a public IP", "Exposed."), ("An edge location", "No."), ("CloudFront", "No.")]),
    (3, "Which statement about security groups is true?", [("They are stateful and contain allow rules only", "Correct."), ("They are stateless", "That is NACLs."), ("They apply at the subnet level", "Instance/ENI level."), ("They support deny rules", "No.")], "You must block a single malicious IP address for an entire subnet. What do you use?", [("A network ACL deny rule", "Correct."), ("A security group deny rule", "Not possible."), ("Route 53", "No."), ("IAM policy", "Not network traffic.")], D + "vpc/latest/userguide/vpc-network-acls.html"),
    (4, "What is Amazon Route 53?", [("A scalable DNS and domain registration service with health checks", "Correct."), ("A load balancer", "No."), ("A CDN", "CloudFront."), ("A VPN", "No.")], "Send users to the Region with the lowest latency and fail over if it is unhealthy. Which service?", [("Route 53 latency-based routing with health checks", "Correct."), ("Security groups", "No."), ("AWS Batch", "No."), ("Amazon SES", "No.")], D + "Route53/latest/DeveloperGuide/Welcome.html"),
    (5, "Which option provides a private, dedicated network connection from on-premises to AWS?", [("AWS Direct Connect", "Correct."), ("AWS Site-to-Site VPN", "Over the internet."), ("Amazon CloudFront", "CDN."), ("Internet gateway", "Public.")], "A company needs encrypted connectivity to its VPC from a branch office by tomorrow. Which option?", [("AWS Site-to-Site VPN", "Correct: quick to set up over the internet."), ("AWS Direct Connect", "Takes longer to provision."), ("VPC peering", "VPC to VPC."), ("Amazon WorkSpaces", "No.")], D + "vpn/latest/s2svpn/VPC_VPN.html"),
], D + "vpc/latest/userguide/what-is-amazon-vpc.html")

# ---------------------------------------------------------------- 3.6
L(id="clf-storage", title="AWS storage services", objectives=ids("3.6", 8), minutes=40,
  objective="Identify uses for object storage, S3 storage classes, block storage (EBS, instance store), file services (EFS, FSx), cached hybrid storage (Storage Gateway), lifecycle policies and AWS Backup.",
  prereqs=[("Compute services", "CLFC02-3.3.1", "clf-compute")],
  foundation=["Amazon S3 stores objects (files) of any size with very high durability, in buckets. Storage classes trade price for access speed.", "Amazon EBS gives EC2 instances persistent disks; instance store is temporary disk attached to the host.",
              "Amazon EFS and Amazon FSx provide shared file systems. AWS Storage Gateway connects on-premises apps to cloud storage. Lifecycle policies and AWS Backup automate data management."],
  engineer=["S3: designed for 11 nines durability; use cases: backups, data lakes, static websites, media, logs. Storage classes: Standard, Intelligent-Tiering, Standard-IA, One Zone-IA, Glacier Instant Retrieval, Glacier Flexible Retrieval, Glacier Deep Archive, Express One Zone. IA and Glacier classes have minimum storage durations and retrieval charges.",
            "Block: Amazon EBS volumes (SSD gp3/io2, HDD st1/sc1) live in one AZ, persist independently of the instance, and support snapshots to S3. Instance store: physically attached, very fast, lost when the instance stops or terminates.",
            "File: Amazon EFS (managed elastic NFS for Linux, Regional across AZs); Amazon FSx (Windows File Server, Lustre for HPC, NetApp ONTAP, OpenZFS).",
            "Hybrid: AWS Storage Gateway (S3 File Gateway, FSx File Gateway, Volume Gateway, Tape Gateway) with local cache.",
            "Lifecycle: S3 Lifecycle rules transition objects between classes and expire them (for example logs to Glacier after 90 days, delete after 7 years). AWS Backup: centralised, policy-based backups across EBS, EC2, RDS, DynamoDB, EFS, FSx, S3 and more, including cross-Region/cross-account copies.",
            "Other: AWS Elastic Disaster Recovery replicates servers for recovery; Snow Family and DataSync move data."],
  anim=("aws-tech-sim", "Open 'Storage choice'."),
  diagram=([("s3", "S3 Standard → IA → Glacier (lifecycle)", 0, 0, "storage"), ("ebs", "EBS (block, one AZ)", 0, 120, "storage"), ("efs", "EFS / FSx (file)", 260, 120, "storage"), ("sgw", "Storage Gateway (on-prem cache)", 260, 0, "network"), ("bk", "AWS Backup (policies)", 520, 60, "service")], [("sgw", "s3"), ("bk", "ebs"), ("bk", "efs"), ("bk", "s3")]),
  example=("Media company storage", ["Raw footage lands in S3 Standard, moves to Glacier Flexible Retrieval after 60 days by lifecycle rule; editors share an FSx for Windows file system; render nodes use instance store scratch space; AWS Backup protects EBS and FSx daily with copies to another Region."]),
  config=cfg(["S3 > Create bucket > Management > Lifecycle rules.", "EC2 > Elastic Block Store > Volumes.", "AWS Backup > Backup plans."], "aws s3 mb s3://media-raw-123\naws s3api put-bucket-lifecycle-configuration --bucket media-raw-123 --lifecycle-configuration file://lifecycle.json\naws backup list-backup-plans", "New-S3Bucket -BucketName media-raw-123\nGet-BAKBackupPlanList"),
  lab=clab("aws-storage", "Storage choice", "storage option"),
  troubleshooting=[("Data lost after stopping an instance.", "It was on instance store.", "Use EBS for persistent data."), ("Unexpected retrieval charges.", "Frequent reads from IA/Glacier classes.", "Use Standard or Intelligent-Tiering for frequently accessed data.")],
  comparisons=[("Azure", "S3 ≈ Blob Storage; EBS ≈ Managed Disks; EFS/FSx ≈ Azure Files/NetApp Files; Storage Gateway ≈ File Sync/StorSimple-style; AWS Backup ≈ Azure Backup.")],
  misconceptions=[("EBS volumes span AZs.", "EBS volumes are in one AZ; snapshots go to S3."), ("S3 One Zone-IA is as resilient as Standard.", "It stores data in a single AZ.")],
  decisions=["Use Intelligent-Tiering for unknown access patterns; automate lifecycle and backups."],
  docs=[("Amazon S3", D + "AmazonS3/latest/userguide/Welcome.html"), ("S3 storage classes", A + "s3/storage-classes/"), ("Amazon EBS", D + "ebs/latest/userguide/what-is-ebs.html"), ("Instance store", D + "AWSEC2/latest/UserGuide/InstanceStorage.html"),
        ("Amazon EFS", D + "efs/latest/ug/whatisefs.html"), ("Amazon FSx", A + "fsx/"), ("AWS Storage Gateway", D + "storagegateway/latest/userguide/WhatIsStorageGateway.html"), ("S3 Lifecycle", D + "AmazonS3/latest/userguide/object-lifecycle-mgmt.html"), ("AWS Backup", D + "aws-backup/latest/devguide/whatisbackup.html")])
pairs("3.6", [
    (1, "Which service provides object storage?", [("Amazon S3", "Correct."), ("Amazon EBS", "Block."), ("Amazon EFS", "File."), ("Instance store", "Block, ephemeral.")], "Which service provides persistent block storage for EC2?", [("Amazon EBS", "Correct."), ("Amazon S3", "Objects."), ("AWS Backup", "Backups."), ("Amazon Glacier", "Archive.")], D + "AmazonS3/latest/userguide/Welcome.html"),
    (2, "Which is a typical use for object storage?", [("Storing backups, media files and data lake data", "Correct."), ("Running an OS boot volume", "Block storage."), ("Hosting a relational database's data files", "Block storage."), ("A shared NFS home directory", "File storage.")], "A company wants to host a static website's HTML, CSS and images cheaply. Which service?", [("Amazon S3 (static website hosting, often with CloudFront)", "Correct."), ("Amazon EBS", "Needs an instance."), ("Amazon RDS", "Database."), ("AWS Batch", "No.")]),
    (3, "Which S3 storage class is lowest cost for long-term archives retrieved within hours?", [("S3 Glacier Deep Archive", "Correct."), ("S3 Standard", "Highest storage cost."), ("S3 Standard-IA", "Millisecond access, more expensive."), ("S3 Intelligent-Tiering", "Automatic tiering.")], "Data is accessed unpredictably. Which class optimises cost automatically?", [("S3 Intelligent-Tiering", "Correct."), ("S3 One Zone-IA", "Fixed tier, single AZ."), ("S3 Glacier Deep Archive", "Archive."), ("S3 Standard", "No automatic savings.")], A + "s3/storage-classes/"),
    (4, "What happens to data on an EC2 instance store when the instance is stopped?", [("It is lost", "Correct."), ("It is kept", "No."), ("It moves to S3", "No."), ("It moves to EBS", "No.")], "A database needs durable block storage that persists when the instance stops. Which storage?", [("Amazon EBS", "Correct."), ("Instance store", "Ephemeral."), ("Amazon S3", "Objects."), ("CloudFront", "CDN.")], D + "AWSEC2/latest/UserGuide/InstanceStorage.html"),
    (5, "Which service provides a managed NFS file system that many Linux instances can mount?", [("Amazon EFS", "Correct."), ("Amazon EBS", "Block."), ("Amazon S3", "Objects."), ("Amazon FSx for Windows", "SMB.")], "Windows applications need SMB shares integrated with Active Directory. Which service?", [("Amazon FSx for Windows File Server", "Correct."), ("Amazon EFS", "NFS/Linux."), ("S3 Glacier", "Archive."), ("Instance store", "No.")], D + "efs/latest/ug/whatisefs.html"),
    (6, "Which service gives on-premises applications access to cloud storage with a local cache?", [("AWS Storage Gateway", "Correct."), ("AWS Snowball", "Offline transfer."), ("Amazon EFS", "In AWS."), ("Amazon CloudFront", "CDN.")], "A branch office wants file shares backed by S3 with frequently used files cached locally. What do you deploy?", [("S3 File Gateway (AWS Storage Gateway)", "Correct."), ("Direct Connect only", "Network."), ("EBS snapshots", "No."), ("AWS Artifact", "No.")], D + "storagegateway/latest/userguide/WhatIsStorageGateway.html"),
    (7, "What do S3 Lifecycle policies do?", [("Transition objects between storage classes and expire them automatically", "Correct."), ("Encrypt objects", "Encryption settings."), ("Replicate to EBS", "No."), ("Grant access", "Policies/ACLs.")], "Logs must move to Glacier after 30 days and be deleted after 1 year. What do you configure?", [("An S3 Lifecycle rule with a transition and an expiration", "Correct."), ("AWS Backup", "Not object transitions."), ("A security group", "No."), ("Route 53", "No.")], D + "AmazonS3/latest/userguide/object-lifecycle-mgmt.html"),
    (8, "What is AWS Backup used for?", [("Centrally managing and automating backups across AWS services", "Correct."), ("Caching content", "CloudFront."), ("DNS", "Route 53."), ("Encryption keys", "KMS.")], "Backups for EBS, RDS and DynamoDB must follow one schedule and be copied to another Region. Which service?", [("AWS Backup with a backup plan and cross-Region copy", "Correct."), ("Separate scripts per service", "Harder to govern."), ("S3 Lifecycle", "Objects only."), ("CloudTrail", "No.")], D + "aws-backup/latest/devguide/whatisbackup.html"),
], A + "s3/storage-classes/")

